-- Keep untouched starter tasks in sync with the clearer examples used for new
-- accounts. Matching both the previous title and description preserves tasks
-- that a user has already renamed or rewritten.
WITH replacements(old_title, old_description, new_title, new_description) AS (
  VALUES
    ('Силовая тренировка на всё тело', 'Комфортная нагрузка с постепенным усложнением.', 'Сделать тренировку дома или в зале', 'Выполнить простую тренировку на основные группы мышц.'),
    ('Быстрая ходьба, бег или велосипед', 'Выберите интенсивность, на которой можете сохранять регулярность.', 'Погулять быстрым шагом 30 минут', 'Выйти на прогулку в удобном темпе; при желании заменить её бегом или велосипедом.'),
    ('Фокус-сессия над главным проектом', 'Один заранее выбранный результат без почты и мессенджеров.', '50 минут поработать над важной задачей', 'Выбрать одну рабочую задачу и на это время закрыть почту и мессенджеры.'),
    ('Запросить конкретную обратную связь', 'У коллеги, руководителя, клиента или наставника.', 'Попросить обратную связь по своей работе', 'Показать результат коллеге или руководителю и спросить, что можно улучшить.'),
    ('Разговор без параллельных дел', 'Позвонить или встретиться и внимательно слушать.', 'Позвонить близкому человеку и поговорить', 'Узнать, как у него дела, и спокойно поговорить без параллельных занятий.'),
    ('Совместное время без телефонов', 'Прогулка, ужин, игра или маленькая поездка.', 'Сходить в кафе или на прогулку с друзьями', 'Договориться о встрече и провести время вместе без спешки.'),
    ('Сфокусированная практика навыка', 'Одна конкретная техника или упражнение за подход.', '25 минут заниматься выбранным навыком', 'Например, пройти упражнение по английскому, рисованию или программированию.'),
    ('Сделать маленький итоговый проект', 'Артефакт, по которому видно, чему вы научились.', 'Сделать небольшую работу с новым навыком', 'Написать текст, нарисовать иллюстрацию, собрать программу или создать другой понятный результат.'),
    ('Еженедельный обзор денег', 'Проверить траты, обязательные платежи и ближайшие решения.', 'Записать траты за неделю', 'Посмотреть историю операций и распределить расходы по основным категориям.'),
    ('Посчитать месяц обязательных расходов', 'Зафиксировать ориентир для первого уровня подушки.', 'Посчитать обязательные расходы за месяц', 'Сложить жильё, продукты, транспорт, связь, кредиты и другие регулярные платежи.'),
    ('Прогулка без ленты и рабочих звонков', 'Оставить внимание телу и окружающему пространству.', 'Погулять 30 минут без рабочих звонков', 'Убрать телефон в карман и пройтись по улице или парку.'),
    ('Вечер без работы', 'Заранее выбрать занятие, после которого легче, а не тяжелее.', 'Провести вечер без работы', 'Посмотреть фильм, почитать, поиграть, принять ванну или выбрать другой спокойный отдых.'),
    ('Творческая сессия без оценки результата', 'Рисовать, писать, снимать, играть или собирать материал.', '45 минут заниматься творчеством', 'Рисовать, писать, фотографировать, играть на инструменте или собирать материал.'),
    ('Показать готовую работу одному человеку', 'Завершение важнее идеальной полировки.', 'Закончить и показать одну работу', 'Выбрать небольшой результат, завершить его и отправить другу или опубликовать.'),
    ('Короткий еженедельный reset дома', 'Вернуть вещи на места и подготовить пространство к новой неделе.', 'Сделать уборку по дому', 'Разложить вещи по местам, протереть пыль, пропылесосить или помыть пол.'),
    ('Устранить одну бытовую помеху', 'Починить, убрать, организовать или автоматизировать то, что раздражает чаще всего.', 'Разобрать одну полку, ящик или шкаф', 'Выбросить ненужное и удобно разложить оставшиеся вещи.')
)
UPDATE "GoalTask" AS task
SET
  "title" = replacements.new_title,
  "description" = replacements.new_description,
  "updatedAt" = CURRENT_TIMESTAMP
FROM replacements
WHERE task."title" = replacements.old_title
  AND task."description" = replacements.old_description;
